SELECT 
  '- Enter Text to Filter Step Definition -' as label, 
  '- Enter Text to Filter Step Definition -' as NAME, 
  null as ID, 
  '- Enter Text to Filter Step Definition -' as value 
FROM 
  STEP_DEFINITION_TEMPLATE_VERBIAGE 
UNION 
SELECT 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as label, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as NAME, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as ID, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as value 
FROM 
  STEP_DEFINITION_TEMPLATE_VERBIAGE 
where 
  IS_POSSIBLE_FIRST_STEP = 'Yes' 
  AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE = 'Yes' 
  AND (CONCAT(',',:STEP_FILTER, ',') like CONCAT('%,', STEP_FILTER, ',%') 
    OR STEP_FILTER LIKE :STEP_DEFINITION_FILTER) 
  AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :FUNCTIONAL_AREA_UUID, ',%')) OR
		(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR
		(COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))
UNION 
SELECT 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as label, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as NAME, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as ID, 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as value 
FROM 
  STEP_DEFINITION_TEMPLATE_VERBIAGE 
where 
  STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID =:STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID




  SELECT STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID FROM STEP_DEFINITION_TEMPLATE_VERBIAGE WHERE STEP_FILTER=:UIFilterTypeForVerBage AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE='Yes' and APPLICABLE_UI_ELEMENT_TYPE in(${strSelectedUIElementType}) AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))




SELECT SDTV.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID FROM STEP_DEFINITION_TEMPLATE_VERBIAGE SDTV INNER JOIN STEP_DEFINITION_ATTRIBUTE SDA ON SDTV.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID = SDA.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID WHERE SDTV.STEP_FILTER=:UIFilterTypeForVerBage AND SDTV.IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE='Yes' AND SDA.STEP_DEFINITION_ATTRIBUTE_MASTER_UUID="adcf6e25-f890-476c-bdcf-e723c6d7894c" order by STEP_DEFINITION_ATTRIBUTE_ID asc



  AND ((CONCAT(',', SDTV.TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', SDTV.FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', SDTV.TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(SDTV.FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(SDTV.TENANT_UUID, '') = '' AND COALESCE(SDTV.FUNCTIONAL_AREA_UUID, '') = ''))


  AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))





  SELECT SDTV.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID FROM STEP_DEFINITION_TEMPLATE_VERBIAGE SDTV INNER JOIN STEP_DEFINITION_ATTRIBUTE SDA ON SDTV.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID = SDA.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID WHERE SDTV.STEP_FILTER=:UIFilterTypeForVerBage AND SDTV.IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE='Yes' AND SDA.STEP_DEFINITION_ATTRIBUTE_MASTER_UUID="adcf6e25-f890-476c-bdcf-e723c6d7894c" AND ((CONCAT(',', SDTV.TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', SDTV.FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', SDTV.TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(SDTV.FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(SDTV.TENANT_UUID, '') = '' AND COALESCE(SDTV.FUNCTIONAL_AREA_UUID, '') = '')) order by STEP_DEFINITION_ATTRIBUTE_ID asc




  SELECT * FROM STEP_DEFINITION_TEMPLATE_VERBIAGE WHERE STEP_FILTER in (${stepDefinitionFilter}) AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE = 'Yes' and APPLICABLE_UI_ELEMENT_TYPE in (${uIElementType}) AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))



  SELECT * FROM STEP_DEFINITION_TEMPLATE_VERBIAGE WHERE STEP_FILTER in(${stepDefinitionFilter}) AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE = 'Yes' AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))




  SELECT ${testSetQueryData[0]['Test Set ID']} as 'Test Set ID', ${testSetQueryData[0]['Test Set ID']} as 'Test Case ID', '' as 'Test Case Step ID', '' as 'Test Case Step Seq ID', ${testCaseStepType} as 'Test Case Step Type', '' as 'Test Case Step Name', STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as 'Step Definition Template', '' as v1, '' as v2, '' as v3, '' as v4, '' as v5, '' as 'Test Case Sep Group Name', '' as reserved2,${testSetQueryData[0]['Test Set ID']} as 'Page ID', 'Active' as Status,uuid() as 'Test Case Step UUID',STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID FROM STEP_DEFINITION_TEMPLATE_VERBIAGE WHERE STEP_FILTER in(${stepDefinitionFilter}) AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE='Yes' and APPLICABLE_UI_ELEMENT_TYPE in(${uIElementType}) AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))




  SELECT ${testSetQueryData[0]['Test Set ID']} as 'Test Set ID', ${testSetQueryData[0]['Test Set ID']} as 'Test Case ID', '' as 'Test Case Step ID', '' as 'Test Case Step Seq ID', ${testCaseStepType} as 'Test Case Step Type', '' as 'Test Case Step Name', STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as 'Step Definition Template', '' as v1, '' as v2, '' as v3, '' as v4, '' as v5, '' as 'Test Case Sep Group Name', '' as reserved2,${testSetQueryData[0]['Test Set ID']} as 'Page ID', 'Active' as Status,uuid() as 'Test Case Step UUID',STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID FROM STEP_DEFINITION_TEMPLATE_VERBIAGE WHERE STEP_FILTER in(${stepDefinitionFilter}) AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE='Yes' AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))



  SELECT * FROM STEP_DEFINITION_TEMPLATE_VERBIAGE WHERE STEP_FILTER=${dataForVerbage} AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE='Yes' AND ((CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(TENANT_UUID, '') = '' AND COALESCE(FUNCTIONAL_AREA_UUID, '') = ''))



  SELECT * FROM STEP_DEFINITION_TEMPLATE_VERBIAGE SDTV INNER JOIN STEP_DEFINITION_ATTRIBUTE SDA ON SDTV.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID = SDA.STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID WHERE SDTV.STEP_FILTER=${dataForVerbage} AND SDTV.IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE='Yes' AND SDA.STEP_DEFINITION_ATTRIBUTE_MASTER_UUID='adcf6e25-f890-476c-bdcf-e723c6d7894c' AND ((CONCAT(',', SDTV.TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND CONCAT(',', SDTV.FUNCTIONAL_AREA_UUID, ',') like CONCAT('%,', :APP_LOGGED_IN_FUNTIONAL_AREA_ID, ',%')) OR(CONCAT(',', SDTV.TENANT_UUID, ',') like CONCAT('%,', :TENANT_UUID, ',%') AND COALESCE(SDTV.FUNCTIONAL_AREA_UUID, '') = '') OR (COALESCE(SDTV.TENANT_UUID, '') = '' AND COALESCE(SDTV.FUNCTIONAL_AREA_UUID, '') = ''))